import { NgModule } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule, ReactiveFormsModule } from '@angular/forms';
import { Routes, RouterModule } from '@angular/router';
import { Geolocation } from '@ionic-native/geolocation/ngx';
import { IonicModule } from '@ionic/angular';
import { IonicSelectableModule } from 'ionic-selectable';

import { NeverenrollmentQuestPageRoutingModule } from './neverenrollment-quest-routing.module';

import { NeverenrollmentQuestPage } from './neverenrollment-quest.page';

const routes: Routes = [
  {
    path: '',
    component: NeverenrollmentQuestPage
  }
];


@NgModule({
  imports: [
    CommonModule,
    FormsModule,
    IonicSelectableModule,
    ReactiveFormsModule,
    IonicModule,
    NeverenrollmentQuestPageRoutingModule,
    RouterModule.forChild(routes)
  ],
  declarations: [NeverenrollmentQuestPage],
  providers: [Geolocation]
})
export class NeverenrollmentQuestPageModule {}
